INSIDE_FUNCTION ! { #[doc = " Wraps a call to `walk_*` / `walk_flat_map_*`"] #[doc = " for an AST node that supports attributes"] #[doc = " (see the `Annotatable` enum)"] #[doc = " This method assigns a `NodeId`, and sets that `NodeId`"] #[doc = " as our current 'lint node id'. If a macro call is found"] #[doc = " inside this AST node, we will use this AST node's `NodeId`"] #[doc = " to emit lints associated with that macro (allowing"] #[doc = " `#[allow]` / `#[deny]` to be applied close to"] #[doc = " the macro invocation)."] #[doc = ""] #[doc = " Do *not* call this for a macro AST node"] #[doc = " (e.g. `ExprKind::MacCall`) - we cannot emit lints"] #[doc = " at these AST nodes, since they are removed and"] #[doc = " replaced with the result of macro expansion."] #[doc = ""] #[doc = " All other `NodeId`s are assigned by `visit_id`."] #[doc = " * `self` is the 'self' parameter for the current method,"] #[doc = " * `id` is a mutable reference to the `NodeId` field"] #[doc = "    of the current AST node."] #[doc = " * `closure` is a closure that executes the"] #[doc = "   `walk_*` / `walk_flat_map_*` method"] #[doc = "   for the current AST node."] #[macro_export] macro_rules ! assign_id { ($ self : ident , $ id : expr , $ closure : expr) => { { let old_id = $ self . cx . current_expansion . lint_node_id ; if $ self . monotonic { debug_assert_eq ! (*$ id , ast :: DUMMY_NODE_ID) ; let new_id = $ self . cx . resolver . next_node_id () ; *$ id = new_id ; $ self . cx . current_expansion . lint_node_id = new_id ;}
let ret = ($ closure) () ; $ self . cx . current_expansion . lint_node_id = old_id ; ret}
}}
}